  }) || null;
}

function isPromptLine(line) {
  const f = fold(line);
  return /medico preferis|que medico|escribi una opcion|boton de abajo|lista completa/.test(f);
}

let hit = findDoc(boton) || findDoc(last);
if (!hit) {
  for (const line of [...lines].reverse()) {
    if (isPromptLine(line)) continue;
    hit = findDoc(line);
    if (hit) break;
  }
}

if (hit) {
  return [{ json: { ...m, med_action: 'save', medico_name: hit.name || last, doctor_id: hit.id, cualquiera: false } }];
}

function isDoctorListRequest(t) {
  const f = fold(t);
  if (!f) return false;
  if (/recomend/.test(f)) return true;
  if (/suger/.test(f) && /medico|doctor|oculista|oftalmologo/.test(f)) return true;
  if (/(que|cuales|cual).{0,40}(otros? )?(medicos?|doctores?|oculistas?|oftalmologos?)/.test(f)) return true;
  if (/(lista|opciones).{0,30}(de )?(medicos?|doctores?|oculistas?)/.test(f)) return true;
  if (/otros? (medicos?|doctores?|oculistas?|oftalmologos?)/.test(f)) return true;
  if (/aparte del (dr|doctor|dra)/.test(f)) return true;
  return false;
}

if (isDoctorListRequest(last) || isDoctorListRequest(texto)) {
  return [{ json: { ...m, med_action: 'list', doctors: docs } }];
}

return [{ json: { ...m, med_action: 'repetir' } }];

